// Evaluates historical accuracy of published PEN=X (USD/PEN) daily forecasts against official BCRP closes.
// Source of truth: data/daily-forecasts.json (generated by engine-daily.js, committed daily via official-data.yml).
// Output: data/official/aciertos-dolar.json with per-horizon stats and prueba_historica block.

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { addBusinessDays, PERU_HOLIDAYS } from "./engine-daily.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DAILY_FORECASTS_PATH = path.join(ROOT, "data", "daily-forecasts.json");
const BCRP_PATH = path.join(ROOT, "data", "official", "bcrp-daily.json");
const PRONOSTICOS_PATH = path.join(ROOT, "data", "official", "pronosticos-dolar.json");
const OUTPUT_PATH = path.join(ROOT, "data", "official", "aciertos-dolar.json");

// Horizons from daily-forecasts.json: h1=1bd, h2=2bd, h5=5bd (semana), h6=6bd, h8=8bd
// We track h1 (día), h5 (semana), h6 (6bd), h8 (8bd) as they appear in daily-forecasts.json
const HORIZONS = {
  h1: { label: "h1", businessDays: 1 },
  h5: { label: "h5", businessDays: 5 },
  h6: { label: "h6", businessDays: 6 },
  h8: { label: "h8", businessDays: 8 },
};

/**
 * Pure function: evaluates published forecasts against actual BCRP closes.
 * @param {Array<Object>} pronosticos - Array of {fecha_base, horizonte, fecha_objetivo, cierre_base, p10, p50, p90}
 * @param {Array<[string, number]>} officialSerie - BCRP daily series [[date, close], ...]
 * @returns {Object} Result per horizon with stats, last 60 cases, and prueba_historica
 */
export function evaluatePublishedForecasts(pronosticos, officialSerie) {
  const officialMap = new Map(officialSerie.map(([d, c]) => [d, c]));

  const today = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Lima",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date());

  const result = {};

  for (const [horizonteKey, { label, businessDays }] of Object.entries(HORIZONS)) {
    const relevant = pronosticos.filter((p) => p.horizonte === label);

    const cases = [];
    let n = 0;
    let dentro = 0;
    let errorMedioCentro = 0;
    let errorMedioPaseoAleatorio = 0;

    for (const p of relevant) {
      const actualClose = officialMap.get(p.fecha_objetivo);

      if (!Number.isFinite(actualClose) || !Number.isFinite(Number(p.p50))) {
        continue;
      }

      n++;
      const p10 = Number(p.p10);
      const p50 = Number(p.p50);
      const p90 = Number(p.p90);
      const cierreBase = Number(p.cierre_base);

      const estaDentro = actualClose >= p10 && actualClose <= p90;
      if (estaDentro) dentro++;

      const errorCentro = Math.abs(actualClose - p50);
      const errorRW = Math.abs(actualClose - cierreBase);

      errorMedioCentro += errorCentro;
      errorMedioPaseoAleatorio += errorRW;

      cases.push({
        fecha_emision: p.fecha_base,
        fecha_objetivo: p.fecha_objetivo,
        p10: Number(p10.toFixed(4)),
        p50: Number(p50.toFixed(4)),
        p90: Number(p90.toFixed(4)),
        cierre: Number(actualClose.toFixed(4)),
        dentro: estaDentro,
      });
    }

    cases.sort((a, b) => b.fecha_emision.localeCompare(a.fecha_emision));
    const last60 = cases.slice(0, 60);

    result[label] = {
      desde: cases.length > 0 ? cases[cases.length - 1].fecha_emision : null,
      n,
      dentro,
      cobertura: n > 0 ? Number(((dentro / n) * 100).toFixed(1)) : null,
      error_medio_centro: n > 0 ? Number((errorMedioCentro / n).toFixed(4)) : null,
      error_medio_paseo_aleatorio: n > 0 ? Number((errorMedioPaseoAleatorio / n).toFixed(4)) : null,
      casos: last60,
    };
  }

  // prueba_historica block copied from research/v7/auditoria-real/resultados-diario-real.json
  const pruebaHistorica = {
    asset: "USD/PEN",
    horizonte: "1 día hábil (siguiente cierre)",
    periodo: "2019-01-02–2026-11-05",
    metodo: "FHS + EWMA(0.94), P50 = paseo aleatorio, K recalibrado con historia hasta cada corte",
    k_recalculo_dias_habiles: 5,
    min_cortes_calibracion: 60,
    cortes: 1958,
    cortes_estables: 1898,
    cobertura_fuera_muestra: 80.59,
    ancho_medio_pct_fuera_muestra: 0.897,
    por_anio: [
      { anio: 2019, n: 249, cobertura: 79.12, ancho_pct: 0.608 },
      { anio: 2020, n: 254, cobertura: 82.68, ancho_pct: 0.965 },
      { anio: 2021, n: 251, cobertura: 82.87, ancho_pct: 1.176 },
      { anio: 2022, n: 251, cobertura: 78.09, ancho_pct: 1.146 },
      { anio: 2023, n: 250, cobertura: 80.00, ancho_pct: 0.773 },
      { anio: 2024, n: 246, cobertura: 78.46, ancho_pct: 0.855 },
      { anio: 2025, n: 248, cobertura: 80.65, ancho_pct: 0.698 },
      { anio: 2026, n: 209, cobertura: 83.25, ancho_pct: 0.961 },
    ],
  };

  return {
    actualizado: today,
    horizontes: result,
    prueba_historica: pruebaHistorica,
  };
}

/**
 * Builds the pronosticos-dolar.json from the latest daily-forecasts.json.
 * Only adds new entries (unique key: fecha_base + horizonte).
 * @returns {Array<Object>} The updated pronosticos array
 */
export function buildPronosticosFromDaily(dailyForecasts, existingPronosticos = []) {
  const existingKeys = new Set(
    existingPronosticos.map((p) => `${p.fecha_base}|${p.horizonte}`)
  );

  const pen = dailyForecasts.simbolos?.PEN;
  if (!pen) return existingPronosticos;

  const fechaBase = pen.fecha_ultimo_cierre;
  const cierreBase = pen.ultimo_cierre;
  const pronosticos = pen.pronosticos;

  const newEntries = [];

  for (const [key, value] of Object.entries(pronosticos)) {
    // Only process h1, h5, h6, h8 (skip h2, h3, h4, h7, manana, semana)
    if (!["h1", "h5", "h6", "h8"].includes(key)) continue;

    const horizonte = key; // h1, h5, h6, h8
    const fechaObjetivo = value.fecha_objetivo;
    const p10 = value.p10;
    const p50 = value.p50;
    const p90 = value.p90;

    const compositeKey = `${fechaBase}|${horizonte}`;
    if (existingKeys.has(compositeKey)) {
      continue; // Already exists, don't overwrite
    }

    newEntries.push({
      fecha_base: fechaBase,
      horizonte,
      fecha_objetivo: fechaObjetivo,
      cierre_base: Number(cierreBase.toFixed(4)),
      p10: Number(p10.toFixed(4)),
      p50: Number(p50.toFixed(4)),
      p90: Number(p90.toFixed(4)),
    });
  }

  // Append new entries to existing, sorted by fecha_base then horizonte
  const all = [...existingPronosticos, ...newEntries].sort((a, b) => {
    const dateCmp = a.fecha_base.localeCompare(b.fecha_base);
    if (dateCmp !== 0) return dateCmp;
    const horizonOrder = { h1: 1, h5: 2, h6: 3, h8: 4 };
    return (horizonOrder[a.horizonte] || 99) - (horizonOrder[b.horizonte] || 99);
  });

  return all;
}

async function main() {
  // Load daily-forecasts.json
  if (!fs.existsSync(DAILY_FORECASTS_PATH)) {
    console.error(`Archivo no encontrado: ${DAILY_FORECASTS_PATH}`);
    process.exit(1);
  }
  const dailyForecasts = JSON.parse(fs.readFileSync(DAILY_FORECASTS_PATH, "utf8"));

  // Load existing pronosticos-dolar.json
  let existingPronosticos = [];
  if (fs.existsSync(PRONOSTICOS_PATH)) {
    existingPronosticos = JSON.parse(fs.readFileSync(PRONOSTICOS_PATH, "utf8"));
  }

  // Build updated pronosticos
  const updatedPronosticos = buildPronosticosFromDaily(dailyForecasts, existingPronosticos);

  // Save pronosticos-dolar.json
  fs.writeFileSync(PRONOSTICOS_PATH, `${JSON.stringify(updatedPronosticos, null, 2)}\n`);
  console.log(`Pronósticos dólar guardados en ${PRONOSTICOS_PATH} (${updatedPronosticos.length} entradas, ${updatedPronosticos.length - existingPronosticos.length} nuevas)`);

  // Load BCRP official series
  if (!fs.existsSync(BCRP_PATH)) {
    console.error(`Archivo no encontrado: ${BCRP_PATH}`);
    process.exit(1);
  }
  const bcrp = JSON.parse(fs.readFileSync(BCRP_PATH, "utf8"));
  const officialSerie = bcrp.series?.PEN?.serie || [];

  // Evaluate
  const result = evaluatePublishedForecasts(updatedPronosticos, officialSerie);

  // Save aciertos-dolar.json
  fs.writeFileSync(OUTPUT_PATH, `${JSON.stringify(result, null, 2)}\n`);
  console.log(`Aciertos dólar guardados en ${OUTPUT_PATH}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((err) => {
    console.error("Error en aciertos-dolar:", err);
    process.exit(1);
  });
}